from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_on_day, points)
        self._earned = {}
        # customer -> list of (day, points)
        self._redeemed = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        points = int(amount // 10)
        if points > 0:
            available_on = day + timedelta(days=14)
            self._earned.setdefault(customer, []).append((available_on, points))
        else:
            self._earned.setdefault(customer, [])
        return points

    def _earned_total(self, customer: str, day: date) -> int:
        total = 0
        for available_on, pts in self._earned.get(customer, ()):
            if available_on <= day:
                total += pts
        return total

    def _redeemed_total(self, customer: str, day: date) -> int:
        total = 0
        for redeem_day, pts in self._redeemed.get(customer, ()):
            if redeem_day <= day:
                total += pts
        return total

    def balance(self, customer: str, day: date) -> int:
        return self._earned_total(customer, day) - self._redeemed_total(customer, day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100.")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points balance.")
        self._redeemed.setdefault(customer, []).append((day, points))
